BEGIN TRANSACTION;
CREATE TABLE block_exercises(id TEXT PRIMARY KEY,block_id TEXT,sequence_order INTEGER,exercise_id TEXT,prescription_type TEXT,quantity REAL,quantity_unit TEXT,intensity_note TEXT,side_note TEXT);
CREATE TABLE equipment(id TEXT PRIMARY KEY,name TEXT UNIQUE,category TEXT);
CREATE TABLE exercise_equipment(exercise_id TEXT,equipment_id TEXT,required INTEGER DEFAULT 1,PRIMARY KEY(exercise_id,equipment_id));
CREATE TABLE exercises(id TEXT PRIMARY KEY,name TEXT,category TEXT,movement_pattern TEXT,modality TEXT,default_unit TEXT,impact_level TEXT,hyrox_relevance REAL,postpartum_friendly INTEGER,notes TEXT);
CREATE TABLE progression_rules(id TEXT PRIMARY KEY,workout_family TEXT,metric TEXT,trigger_condition TEXT,action TEXT,max_change_pct REAL,notes TEXT);
CREATE TABLE substitutions(id TEXT PRIMARY KEY,exercise_id TEXT,substitute_exercise_id TEXT,reason TEXT,priority INTEGER);
CREATE TABLE tags(id TEXT PRIMARY KEY,name TEXT UNIQUE,tag_type TEXT);
CREATE TABLE workout_blocks(id TEXT PRIMARY KEY,workout_id TEXT,block_order INTEGER,block_type TEXT,title TEXT,instructions TEXT,rounds INTEGER,duration_minutes REAL,rest_seconds INTEGER);
CREATE TABLE workout_tags(workout_id TEXT,tag_id TEXT,PRIMARY KEY(workout_id,tag_id));
CREATE TABLE workout_templates(id TEXT PRIMARY KEY,name TEXT,workout_family TEXT,primary_goal TEXT,secondary_goal TEXT,estimated_minutes INTEGER,intensity_target TEXT,impact_level TEXT,hyrox_specificity REAL,postpartum_friendly INTEGER,requires_running INTEGER,requires_ski INTEGER,description TEXT,coaching_notes TEXT);
CREATE TABLE workout_variants(id TEXT PRIMARY KEY,workout_id TEXT,variant_code TEXT,time_budget_minutes INTEGER,recovery_state TEXT,volume_multiplier REAL,intensity_modifier TEXT,notes TEXT,UNIQUE(workout_id,variant_code));
COMMIT;
